.ic-drop{border:1px solid var(--line-strong);border-radius:var(--r-md);
  background:var(--surface-2);box-shadow:var(--e-well);padding:var(--s5);text-align:center}
.ic-drop.over{border-color:var(--accent);background:var(--surface)}
.ic-drop p{margin:0 0 var(--s3)}
.ip-list{margin-top:var(--s5)}
.ip-list:empty{display:none}
.ip-row{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:var(--s3);
  align-items:center;padding:10px 0;border-top:1px solid var(--line)}
.ip-row img{width:44px;height:44px;object-fit:cover;border-radius:var(--r-sm);background:var(--surface-2)}
.ip-name{font-size:var(--t-14);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ip-sub{font-family:var(--font-mono);font-size:var(--t-12);color:var(--muted)}
.ip-btns{display:flex;gap:6px}
.ip-btns button{width:34px;height:34px;padding:0;position:relative}
.ip-btns button::before{content:"";position:absolute;left:50%;top:50%;
  width:44px;height:44px;transform:translate(-50%,-50%)}
.ip-err{color:var(--danger)}

