(function(){
  var $=function(id){return document.getElementById(id)};
  var items=[], busy=false;

  // ---- a minimal PDF writer -------------------------------------------
  // Every image is re-encoded to baseline JPEG through a canvas, so it can
  // be embedded with /DCTDecode and copied in byte for byte. That avoids
  // implementing Flate and sidesteps CMYK JPEGs, which need a different
  // color space and a Decode array to render correctly.
  function enc(s){ var a=new Uint8Array(s.length); for(var i=0;i<s.length;i++) a[i]=s.charCodeAt(i)&0xff; return a; }
  function buildPDF(pages){
    var objs=[], parts=[];
    var kids=pages.map(function(_,i){ return (3+i*3)+' 0 R'; }).join(' ');
    objs[1]='<</Type/Catalog/Pages 2 0 R>>';
    objs[2]='<</Type/Pages/Kids['+kids+']/Count '+pages.length+'>>';
    pages.forEach(function(p,i){
      var pg=3+i*3, ct=pg+1, im=pg+2;
      objs[pg]='<</Type/Page/Parent 2 0 R/MediaBox[0 0 '+p.pw.toFixed(2)+' '+p.ph.toFixed(2)+']'+
        '/Resources<</XObject<</Im0 '+im+' 0 R>>>>/Contents '+ct+' 0 R>>';
      var stream='q '+p.dw.toFixed(2)+' 0 0 '+p.dh.toFixed(2)+' '+p.dx.toFixed(2)+' '+p.dy.toFixed(2)+' cm /Im0 Do Q';
      objs[ct]={dict:'<</Length '+stream.length+'>>', data:enc(stream)};
      objs[im]={dict:'<</Type/XObject/Subtype/Image/Width '+p.iw+'/Height '+p.ih+
        '/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length '+p.bytes.length+'>>',
        data:p.bytes};
    });
    var offsets=[], pos=0;
    function push(u8){ parts.push(u8); pos+=u8.length; }
    push(enc('%PDF-1.4\n%\u00E2\u00E3\u00CF\u00D3\n'));
    for(var n=1;n<objs.length;n++){
      offsets[n]=pos;
      var o=objs[n];
      if(typeof o==='string'){ push(enc(n+' 0 obj\n'+o+'\nendobj\n')); }
      else {
        push(enc(n+' 0 obj\n'+o.dict+'\nstream\n'));
        push(o.data);
        push(enc('\nendstream\nendobj\n'));
      }
    }
    var xref=pos, count=objs.length;
    var x='xref\n0 '+count+'\n0000000000 65535 f \n';
    for(var n2=1;n2<count;n2++) x+=('0000000000'+offsets[n2]).slice(-10)+' 00000 n \n';
    x+='trailer\n<</Size '+count+'/Root 1 0 R>>\nstartxref\n'+xref+'\n%%EOF\n';
    push(enc(x));
    return new Blob(parts,{type:'application/pdf'});
  }

  var SIZES={a4:[595.28,841.89], a4l:[841.89,595.28], letter:[612,792]};
  function jpegOf(img,q){
    return new Promise(function(res,rej){
      var c=document.createElement('canvas');
      // guard the iOS canvas area limit, which silently yields a blank image
      var w=img.width,h=img.height,MAX=16000000;
      if(w*h>MAX){ var s=Math.sqrt(MAX/(w*h)); w=Math.round(w*s); h=Math.round(h*s); }
      c.width=w; c.height=h;
      var ctx=c.getContext('2d');
      ctx.fillStyle='#fff'; ctx.fillRect(0,0,w,h);   // JPEG has no transparency
      ctx.drawImage(img,0,0,w,h);
      c.toBlob(function(b){
        if(!b) return rej(new Error('could not encode'));
        b.arrayBuffer().then(function(ab){ res({bytes:new Uint8Array(ab),w:w,h:h}); },rej);
      },'image/jpeg',q);
    });
  }
  function loadImage(file){
    return new Promise(function(res,rej){
      var url=URL.createObjectURL(file), im=new Image();
      im.onload=function(){ res({el:im,url:url}); };
      im.onerror=function(){ URL.revokeObjectURL(url); rej(new Error('could not read')); };
      im.src=url;
    });
  }
  function fmt(n){ return n<1024?n+' B':n<1048576?(n/1024).toFixed(0)+' KB':(n/1048576).toFixed(2)+' MB'; }

  function paint(){
    $('list').innerHTML=items.map(function(it,i){
      return '<div class="ip-row"><img src="'+it.url+'" alt="">'+
        '<div><div class="ip-name">'+it.name.replace(/[<>&]/g,'')+'</div>'+
        '<div class="ip-sub'+(it.err?' ip-err':'')+'">'+(it.err||(it.w+' x '+it.h+' · '+fmt(it.size)))+'</div></div>'+
        '<div class="ip-btns">'+
        '<button type="button" data-up="'+i+'" aria-label="Move up"'+(i===0?' disabled':'')+'>↑</button>'+
        '<button type="button" data-down="'+i+'" aria-label="Move down"'+(i===items.length-1?' disabled':'')+'>↓</button>'+
        '<button type="button" data-rm="'+i+'" aria-label="Remove">×</button></div></div>';
    }).join('');
    var ok=items.filter(function(i){return !i.err});
    $('npages').textContent=ok.length;
    $('nsize').textContent=fmt(ok.reduce(function(a,b){return a+b.size},0));
    $('go').disabled=!ok.length||busy;
    $('clear').disabled=!items.length||busy;
    if(window.WT) WT.resize();
  }
  function add(files){
    var list=Array.prototype.slice.call(files||[]);
    var seq=list.map(function(f){
      return function(){
        if(!/^image\//.test(f.type)){
          items.push({name:f.name||'file',err:'Not an image, skipped',url:'',size:0}); return Promise.resolve();
        }
        return loadImage(f).then(function(r){
          items.push({name:f.name,file:f,url:r.url,el:r.el,w:r.el.naturalWidth,h:r.el.naturalHeight,size:f.size});
        },function(){ items.push({name:f.name||'file',err:'Could not read this file',url:'',size:0}); });
      };
    });
    seq.reduce(function(p,fn){return p.then(fn)},Promise.resolve()).then(paint);
  }
  $('pick').addEventListener('click',function(){$('file').click()});
  $('file').addEventListener('change',function(){ add(this.files); this.value=''; });
  var drop=$('drop');
  ['dragenter','dragover'].forEach(function(e){drop.addEventListener(e,function(ev){ev.preventDefault();drop.classList.add('over')})});
  ['dragleave','drop'].forEach(function(e){drop.addEventListener(e,function(ev){ev.preventDefault();drop.classList.remove('over')})});
  drop.addEventListener('drop',function(ev){ add(ev.dataTransfer.files); });
  $('list').addEventListener('click',function(e){
    var b=e.target.closest('button'); if(!b||busy) return;
    var d=b.dataset;
    if(d.rm!==undefined){ var it=items.splice(+d.rm,1)[0]; if(it.url) URL.revokeObjectURL(it.url); }
    else if(d.up!==undefined){ var i=+d.up; items.splice(i-1,0,items.splice(i,1)[0]); }
    else if(d.down!==undefined){ var j=+d.down; items.splice(j+1,0,items.splice(j,1)[0]); }
    paint();
  });
  $('clear').addEventListener('click',function(){
    items.forEach(function(i){ if(i.url) URL.revokeObjectURL(i.url); });
    items=[]; $('nout').textContent='0'; $('note').textContent='Nothing is uploaded. The PDF is written on your device.'; paint();
  });

  $('go').addEventListener('click',function(){
    var ok=items.filter(function(i){return !i.err});
    if(!ok.length||busy) return;
    busy=true; paint();
    $('note').textContent='Building the PDF…';
    var q=parseFloat($('q').value), mode=$('size').value, pages=[];
    ok.reduce(function(p,it){
      return p.then(function(){
        return jpegOf(it.el,q).then(function(j){
          var pw,ph,dw,dh,dx,dy;
          if(mode==='fit'){
            // 72 points per inch; treat the image as 96 dpi so a screenshot
            // comes out roughly life size on the page
            pw=j.w*72/96; ph=j.h*72/96; dw=pw; dh=ph; dx=0; dy=0;
          } else {
            var s=SIZES[mode]; pw=s[0]; ph=s[1];
            var m=28, aw=pw-m*2, ah=ph-m*2;
            var r=Math.min(aw/j.w, ah/j.h);
            dw=j.w*r; dh=j.h*r; dx=(pw-dw)/2; dy=(ph-dh)/2;
          }
          pages.push({pw:pw,ph:ph,dw:dw,dh:dh,dx:dx,dy:dy,iw:j.w,ih:j.h,bytes:j.bytes});
        });
      });
    },Promise.resolve()).then(function(){
      var blob=buildPDF(pages);
      $('nout').textContent=fmt(blob.size);
      var u=URL.createObjectURL(blob),a=document.createElement('a');
      a.href=u; a.download='images.pdf'; document.body.appendChild(a); a.click();
      setTimeout(function(){URL.revokeObjectURL(u);a.remove()},8000);
      $('note').textContent='Done. '+pages.length+' page'+(pages.length>1?'s':'')+', '+fmt(blob.size)+'. Nothing was uploaded.';
    }).catch(function(err){
      $('note').textContent='Could not build the PDF: '+(err&&err.message||'unknown problem');
    }).then(function(){ busy=false; paint(); });
  });
  paint();
})();
